export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0, 0, -2));
  camera.alpha = -1.57;
  camera.beta = 0.442;
  camera.radius = 12.6;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  // camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.8;

  createTiledGround();

  var vertices = [
    new BABYLON.Vector3(-1.46, 0, -3.04),
    new BABYLON.Vector3(-2.19, 0, -0.98),
    new BABYLON.Vector3(-1.3, 0, -0.63),
    new BABYLON.Vector3(0.11, 0, -0.99),
    new BABYLON.Vector3(0.6, 0, -2.33),
  ];

  var vertexSpheres = [];
  var midpointSpheres = [];
  var polygonLines = null;
  var tempPolygonLines = null;
  var polygonMesh = null;
  var polygonDragBehavior = null;

  const zoneColor = BABYLON.Color3.Random();

  let hasDragged = false;

  function createDragSphere(position, color, onDrag, onDragEnd, transparent = false, vertexIndex = null, isTemp = false) {
    const sphere = BABYLON.MeshBuilder.CreateSphere("dragSphere", { diameter: 0.2 }, scene);
    sphere.position.copyFrom(position);
    sphere.renderOutline = true;
    sphere.outlineColor = zoneColor;
    sphere.renderingGroupId = 1;

    sphere.metadata = {};
    if (isTemp) {
      sphere.metadata.isTemp = true;
      sphere.name += " temp";

      sphere.actionManager = new BABYLON.ActionManager(scene);
      sphere.actionManager.registerAction(
        new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOverTrigger, () => showTooltip(sphere, "클릭 후 드래그하여 추가 지점 생성"))
      );
      sphere.actionManager.registerAction(new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOutTrigger, () => hideTooltip()));
    } else {
      sphere.metadata.vertexRef = position;

      sphere.actionManager = new BABYLON.ActionManager(scene);
      sphere.actionManager.registerAction(
        new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnDoublePickTrigger, function () {
          const vRef = sphere.metadata.vertexRef;
          const index = vertices.findIndex((v) => v === vRef);
          if (index !== -1 && vertices.length > 3) {
            vertices.splice(index, 1);
            hideTooltip();

            sphere.dispose();
            recreatePolygon();
          }
        })
      );

      sphere.actionManager.registerAction(
        new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOverTrigger, () =>
          showTooltip(sphere, "1. 클릭 후 드래그하여 영역 수정\n2. 더블 클릭하여 삭제")
        )
      );
      sphere.actionManager.registerAction(new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOutTrigger, () => hideTooltip()));
    }

    const mat = new BABYLON.StandardMaterial("mat", scene);
    mat.diffuseColor = color;
    mat.disableLighting = true;
    mat.emissiveColor = color;
    mat.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
    if (transparent) mat.alpha = 0.5;
    sphere.material = mat;

    const drag = new BABYLON.PointerDragBehavior({ dragPlaneNormal: new BABYLON.Vector3(0, 1, 0) });
    drag.useObjectOrientationForDragging = false;
    drag.onDragObservable.add((e) => {
      hasDragged = true;
      sphere.position.y = 0;
      if (onDrag) onDrag(sphere.position.clone());
      camera.detachControl();
    });

    drag.onDragEndObservable.add((e) => {
      if (hasDragged && onDragEnd) {
        onDragEnd(sphere.position.clone());
      }
      hasDragged = false;
    });
    sphere.addBehavior(drag);

    return sphere;
  }

  function updateLinesOnly() {
    const linePoints = [...vertices, vertices[0]];
    const positions = [];
    linePoints.forEach((p) => {
      positions.push(p.x, p.y, p.z);
    });

    if (!polygonLines) {
      polygonLines = BABYLON.MeshBuilder.CreateLines(
        "poly",
        {
          points: linePoints,
          updatable: true,
        },
        scene
      );
      polygonLines.color = zoneColor;
    } else {
      polygonLines.updateVerticesData(BABYLON.VertexBuffer.PositionKind, positions);
    }
  }

  function updateTempLinesWith(tempVerts) {
    const linePoints = [...tempVerts, tempVerts[0]];
    const positions = [];
    linePoints.forEach((p) => {
      positions.push(p.x, p.y, p.z);
    });

    if (!tempPolygonLines || !tempPolygonLines.isVerticesDataPresent(BABYLON.VertexBuffer.PositionKind)) {
      tempPolygonLines?.dispose();
      tempPolygonLines = BABYLON.MeshBuilder.CreateLines(
        "tempPoly",
        {
          points: linePoints,
          updatable: true,
        },
        scene
      );
      tempPolygonLines.color = zoneColor;
      tempPolygonLines.alpha = 0.6;
      tempPolygonLines.isPickable = false;
    } else {
      tempPolygonLines.updateVerticesData(BABYLON.VertexBuffer.PositionKind, positions);
    }
  }

  function updatePolygonMesh() {
    if (polygonMesh) {
      polygonMesh.dispose();
      polygonMesh = null;
    }

    scene.meshes.filter((m) => m.name === "polyMesh" && m !== polygonMesh).forEach((m) => m.dispose());

    const shape2D = vertices.map((v) => new BABYLON.Vector2(v.x, v.z));
    const polygonBuilder = new BABYLON.PolygonMeshBuilder("polyMesh", shape2D, scene);
    polygonMesh = polygonBuilder.build(true, 0.01);
    polygonMesh.name = "polyMesh";

    polygonMesh.actionManager = new BABYLON.ActionManager(scene);
    polygonMesh.actionManager.registerAction(
      new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOverTrigger, () => showTooltip(polygonMesh, "클릭 후 드래그하여 이동", true))
    );
    polygonMesh.actionManager.registerAction(new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOutTrigger, () => hideTooltip()));

    const mat = new BABYLON.StandardMaterial("faceMat", scene);
    mat.diffuseColor = zoneColor;
    mat.alpha = 0.3;
    mat.backFaceCulling = false;
    mat.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
    mat.zOffset = -10;
    polygonMesh.material = mat;

    if (polygonDragBehavior) {
      polygonMesh.removeBehavior(polygonDragBehavior);
    }

    polygonDragBehavior = new BABYLON.PointerDragBehavior({ dragPlaneNormal: new BABYLON.Vector3(0, 1, 0) });
    polygonDragBehavior.useObjectOrientationForDragging = false;

    polygonDragBehavior.onDragStartObservable.add(() => {
      camera.detachControl();
    });

    polygonDragBehavior.onDragObservable.add((event) => {
      const delta = event.delta;
      vertices.forEach((v, i) => {
        v.addInPlace(delta);
        vertexSpheres[i].position.addInPlace(delta);
      });
      midpointSpheres.forEach((s) => s.position.addInPlace(delta));

      updateLinesOnly();
      if (polygonMesh) polygonMesh.position.addInPlace(delta);
    });

    polygonDragBehavior.onDragEndObservable.add(() => {
      // camera.attachControl(canvas, true);
      recreatePolygon();
    });

    polygonMesh.addBehavior(polygonDragBehavior);
  }

  function recreatePolygon() {
    vertexSpheres.forEach((s) => s.dispose());
    midpointSpheres.forEach((s) => s.dispose());
    if (tempPolygonLines) {
      tempPolygonLines.dispose();
      tempPolygonLines = null;
    }

    vertexSpheres = [];
    midpointSpheres = [];

    // sphere
    for (let i = 0; i < vertices.length; i++) {
      const vertex = vertices[i];
      const sphere = createDragSphere(
        vertex,
        new BABYLON.Color3(1, 1, 1),
        (newPos) => {
          vertex.copyFrom(newPos);
          updateLinesOnly();
        },
        (newPos) => {
          vertex.copyFrom(newPos);
          recreatePolygon();
        }
      );

      vertexSpheres.push(sphere);
    }

    // temp sphere
    for (let i = 0; i < vertices.length; i++) {
      const a = vertices[i];
      const b = vertices[(i + 1) % vertices.length];
      const mid = BABYLON.Vector3.Center(a, b);
      const insertIndex = i + 1;
      const sphere = createDragSphere(
        mid,
        new BABYLON.Color3(1, 1, 1),
        (newPos) => {
          const tempVertices = [...vertices];
          tempVertices.splice(insertIndex, 0, newPos);
          updateTempLinesWith(tempVertices);
        },
        (newPos) => {
          if (tempPolygonLines) {
            tempPolygonLines.dispose();
            tempPolygonLines = null;
          }
          vertices.splice(insertIndex, 0, newPos);
          recreatePolygon();
        },
        true,
        null,
        true
      );
      sphere.scaling.scaleInPlace(0.7);
      midpointSpheres.push(sphere);
    }

    if (polygonLines) polygonLines.dispose();
    const linePoints = [...vertices, vertices[0]];
    polygonLines = BABYLON.MeshBuilder.CreateLines(
      "poly",
      {
        points: linePoints,
        updatable: true,
      },
      scene
    );
    polygonLines.color = zoneColor;

    updateLinesOnly();
    updatePolygonMesh();
  }

  recreatePolygon();

  function lonLatToTileXY(lon, lat, zoom) {
    const x = Math.floor(((lon + 180) / 360) * Math.pow(2, zoom));
    const y = Math.floor(((1 - Math.log(Math.tan((lat * Math.PI) / 180) + 1 / Math.cos((lat * Math.PI) / 180)) / Math.PI) / 2) * Math.pow(2, zoom));
    return { x, y };
  }

  function createTiledGround() {
    // Part 1 : Creation of Tiled Ground
    var xmin = -10;
    var zmin = -10;
    var xmax = 10;
    var zmax = 10;
    var precision = {
      w: 2,
      h: 2,
    };
    var subdivisions = {
      h: 8,
      w: 8,
    };
    // Create the Tiled Ground
    var tiledGround = BABYLON.MeshBuilder.CreateTiledGround(
      "Tiled Ground",
      {
        xmin: xmin,
        zmin: zmin,
        xmax: xmax,
        zmax: zmax,
        subdivisions: subdivisions,
        precision: precision,
      },
      scene
    );
    tiledGround.position.y = -0.1;

    // Part 2 : Create the multi material
    // Create differents materials
    var whiteMaterial = new BABYLON.StandardMaterial("White", scene);
    whiteMaterial.diffuseColor = new BABYLON.Color3(1, 1, 1);

    var blackMaterial = new BABYLON.StandardMaterial("Black", scene);
    blackMaterial.diffuseColor = new BABYLON.Color3(0, 0, 0);

    // Create Multi Material
    var multimat = new BABYLON.MultiMaterial("multi", scene);
    var zoom = 18;
    const seoul = lonLatToTileXY(127.028344, 37.496966, zoom);

    var xTileBase = seoul.x;
    var yTileBase = seoul.y;

    for (var row = 0; row < subdivisions.h; row++) {
      for (var col = 0; col < subdivisions.w; col++) {
        var material = new BABYLON.StandardMaterial("material" + row + "-" + col, scene);
        material.diffuseTexture = new BABYLON.Texture(
          "https://b.tile.openstreetmap.org/" + zoom + "/" + (xTileBase + col) + "/" + (yTileBase - row) + ".png",
          scene
        );
        material.diffuseTexture.wrapU = BABYLON.Texture.CLAMP_ADDRESSMODE;
        material.diffuseTexture.wrapV = BABYLON.Texture.CLAMP_ADDRESSMODE;
        material.specularColor = new BABYLON.Color4(0, 0, 0, 0);
        material.backFaceCulling = false;
        multimat.subMaterials.push(material);
      }
    }

    // Part 3 : Apply the multi material
    // Define multimat as material of the tiled ground
    tiledGround.material = multimat;

    // Needed variables to set subMeshes
    var verticesCount = tiledGround.getTotalVertices();
    var tileIndicesLength = tiledGround.getIndices().length / (subdivisions.w * subdivisions.h);

    // Set subMeshes of the tiled ground
    tiledGround.subMeshes = [];
    var index = 0;
    var base = 0;
    for (var row = 0; row < subdivisions.h; row++) {
      for (var col = 0; col < subdivisions.w; col++) {
        var submesh = new BABYLON.SubMesh(index++, 0, verticesCount, base, tileIndicesLength, tiledGround);
        tiledGround.subMeshes.push(submesh);
        base += tileIndicesLength;
      }
    }
  }

  const tooltipUI = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("tooltipUI");

  const tooltipRect = new BABYLON.GUI.Rectangle();
  tooltipRect.width = "250px";
  tooltipRect.height = "60px";
  tooltipRect.cornerRadius = 8;
  tooltipRect.thickness = 2;
  tooltipRect.color = "white";
  tooltipRect.background = "#333333";
  tooltipRect.isVisible = false;

  const tooltipText = new BABYLON.GUI.TextBlock();
  tooltipText.color = "white";
  tooltipText.fontSize = 14;
  tooltipText.textWrapping = true;
  tooltipText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
  tooltipText.textVerticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;

  tooltipRect.addControl(tooltipText);
  tooltipUI.addControl(tooltipRect);

  function showTooltip(mesh, message, isPolygon = false) {
    if (!mesh) return;

    tooltipRect.linkWithMesh(mesh);
    tooltipText.text = message;
    if (isPolygon) {
      tooltipRect.linkOffsetY = "80px";
    } else {
      tooltipRect.linkOffsetY = "-80px";
    }
    tooltipRect.isVisible = true;
  }

  function hideTooltip() {
    tooltipRect.linkWithMesh(null);
    tooltipRect.isVisible = false;
  }

  return scene;
}
